def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

primes_below_20 = [i for i in range(2, 20) if is_prime(i)]
print(len(primes_below_20))
